import{_ as r,C as a,o,c as l,j as t,a as i,G as s,a3 as p}from"./chunks/framework.Bvm_liKL.js";const k=JSON.parse('{"title":"解决方案结构","description":"各项目的职责与依赖关系","frontmatter":{"title":"解决方案结构","description":"各项目的职责与依赖关系"},"headers":[],"relativePath":"cn/dev/getting-started/solution-layout.md","filePath":"cn/dev/getting-started/solution-layout.md"}'),c={name:"cn/dev/getting-started/solution-layout.md"};function b(u,n,g,h,m,P){const e=a("ArticleMetadata"),d=a("HelpUsImprove");return o(),l("div",null,[n[0]||(n[0]=t("h1",{id:"解决方案结构",tabindex:"-1"},[i("解决方案结构 "),t("a",{class:"header-anchor",href:"#解决方案结构","aria-label":'Permalink to "解决方案结构"'},"​")],-1)),s(e),s(d),n[1]||(n[1]=p(`<p><code>Ink Canvas.sln</code> 包含 6 个项目。磁盘上另有 2 个项目（<code>InkCanvas.PowerPointAddIn</code>、<code>InkCanvas.NativeInk.Tests</code>）<strong>未加入解决方案</strong>，需要单独打开构建。</p><h2 id="项目一览" tabindex="-1">项目一览 <a class="header-anchor" href="#项目一览" aria-label="Permalink to &quot;项目一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>目标框架</th><th>输出</th><th>职责</th></tr></thead><tbody><tr><td><strong>InkCanvasForClass</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>WinExe</td><td>主程序。所有 UI、墨迹、PPT 联动、自动化、插件宿主都在这里</td></tr><tr><td><strong>InkCanvas.PluginSdk</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>Library + NuGet</td><td>插件 SDK。接口与宿主服务抽象，插件项目引用它</td></tr><tr><td><strong>InkCanvas.Controls</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>Library + NuGet</td><td>宿主与插件共用的 WPF 控件（工具栏按钮、颜色选择、设置卡片、弹窗外壳）</td></tr><tr><td><strong>InkCanvas.IACoreHelper</strong></td><td><strong>.NET Framework 4.7.2</strong></td><td>Exe (x86)</td><td>外挂进程，为主程序提供 IACore 墨迹形状/文字识别</td></tr><tr><td><strong>InkCanvas.SettingsTreeView</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>WinExe</td><td>独立小工具，树形查看设置项结构</td></tr><tr><td><strong>InkCanvas.PPTAgent.Contracts</strong></td><td><code>netstandard2.0</code></td><td>Library</td><td>主程序与 PPT VSTO 加载项之间的 IPC 契约</td></tr></tbody></table><p>未在 sln 中：</p><table tabindex="0"><thead><tr><th>项目</th><th>目标框架</th><th>说明</th></tr></thead><tbody><tr><td><strong>InkCanvas.PowerPointAddIn</strong></td><td>.NET Framework 4.7.2 (VSTO)</td><td>PowerPoint 加载项，采集放映状态推送给主程序</td></tr><tr><td><strong>InkCanvas.NativeInk.Tests</strong></td><td>—</td><td>原生墨迹相关测试</td></tr></tbody></table><h2 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to &quot;依赖关系&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>InkCanvasForClass (主程序)</span></span>
<span class="line"><span>  ├─&gt; InkCanvas.PluginSdk</span></span>
<span class="line"><span>  ├─&gt; InkCanvas.Controls</span></span>
<span class="line"><span>  └─&gt; InkCanvas.PPTAgent.Contracts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>InkCanvas.PowerPointAddIn (VSTO，独立构建)</span></span>
<span class="line"><span>  └─&gt; InkCanvas.PPTAgent.Contracts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>InkCanvas.IACoreHelper</code> 与 <code>InkCanvas.SettingsTreeView</code> 都是独立可执行程序，不被主程序引用，通过进程间通信或手工运行。</p><h2 id="为什么框架版本不统一" tabindex="-1">为什么框架版本不统一 <a class="header-anchor" href="#为什么框架版本不统一" aria-label="Permalink to &quot;为什么框架版本不统一&quot;">​</a></h2><p>三种目标框架并存，各有原因：</p><ul><li><strong>主程序用 net6.0-windows</strong>：需要 WPF、WinRT 墨迹分析（<code>InkAnalyzer</code>）、现代 .NET 性能。</li><li><strong>IACoreHelper 用 .NET Framework 4.7.2 + x86</strong>：IACore 原生库是 32 位 COM 组件，主程序如果直接加载会把自己锁死在 32 位。拆成独立 x86 进程，主程序保持 AnyCPU/64 位，两者通过命名管道 + 共享内存通信。</li><li><strong>PPTAgent.Contracts 用 netstandard2.0</strong>：它要同时被 net6 的主程序和 .NET Framework 4.7.2 的 VSTO 加载项引用，netstandard2.0 是两者的公共分母。</li><li><strong>PowerPointAddIn 用 .NET Framework 4.7.2</strong>：VSTO 加载项模型不支持 .NET 6。</li></ul><h2 id="主程序内部结构" tabindex="-1">主程序内部结构 <a class="header-anchor" href="#主程序内部结构" aria-label="Permalink to &quot;主程序内部结构&quot;">​</a></h2><p><code>Ink Canvas/</code> 下的目录划分：</p><table tabindex="0"><thead><tr><th>目录</th><th>内容</th></tr></thead><tbody><tr><td><code>Automation/</code></td><td>自动化引擎。Trigger/Rule/Action 三段式，见 <a href="/website/cn/dev/core/automation">自动化引擎</a></td></tr><tr><td><code>Controls/</code></td><td>内嵌 WPF 控件。<code>Toolbar/</code> 是工具栏体系，<code>Popups/</code> 是各工具弹层</td></tr><tr><td><code>Helpers/</code></td><td>最大的一块（约 105 个文件）。墨迹平滑与识别、PPT 联动、性能监控、窗口管理、摄像头、云上传等</td></tr><tr><td><code>Plugins/</code></td><td>插件宿主实现。<code>PluginManager.cs</code> 是核心</td></tr><tr><td><code>Windows/</code></td><td>各个独立窗口（设置、启动画面等）</td></tr><tr><td><code>Resources/</code></td><td>图标、图片、字体等资源</td></tr></tbody></table><p><code>MainWindow</code> 被拆成多个 partial 文件，详见 <a href="/website/cn/dev/core/mainwindow">主窗口</a>。</p><h2 id="配置文件位置" tabindex="-1">配置文件位置 <a class="header-anchor" href="#配置文件位置" aria-label="Permalink to &quot;配置文件位置&quot;">​</a></h2><p>运行时配置都在<strong>程序目录</strong>下（不是 <code>%AppData%</code>）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;程序目录&gt;/</span></span>
<span class="line"><span>├── Configs/</span></span>
<span class="line"><span>│   ├── Settings.json          # 主设置</span></span>
<span class="line"><span>│   └── disabled_plugins.json  # 被禁用的插件列表</span></span>
<span class="line"><span>├── Plugins/                    # 已安装插件</span></span>
<span class="line"><span>├── PluginPackages/            # 待安装的 .icpx 包</span></span>
<span class="line"><span>├── PluginConfigs/             # 各插件的配置</span></span>
<span class="line"><span>├── PluginLogs/                # 插件日志</span></span>
<span class="line"><span>├── Logs/                       # 主程序日志</span></span>
<span class="line"><span>└── Crashes/                    # 崩溃转储</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">便携化的代价</p><p>配置放在程序目录让软件可以绿色便携，但如果安装到 <code>C:\\Program Files\\</code> 且没有写权限，配置会保存失败。这是设计权衡，改动时要注意。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./build-and-run">构建与运行</a> — 版本号、CI、打包</li><li><a href="./contributing">贡献流程</a> — 提交规范</li></ul>`,21))])}const v=r(c,[["render",b]]);export{k as __pageData,v as default};
